import datetime,json,pathlib,subprocess,os,re,stat
base=pathlib.Path('/Users/alexy/src/sail-extensions-gates')
result={'started_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'hostname':os.uname().nodename,'commands':[]}
def run(cmd,timeout=35):
 entry={'command':cmd,'started_utc':datetime.datetime.now(datetime.timezone.utc).isoformat()}
 try:
  r=subprocess.run(cmd,capture_output=True,text=True,timeout=timeout)
  entry.update(exit_code=r.returncode,stdout=r.stdout,stderr=r.stderr)
 except subprocess.TimeoutExpired as e:
  entry.update(error='TIMEOUT_CHILD_KILLED_AND_REAPED',stdout=e.stdout.decode(errors='replace') if isinstance(e.stdout,bytes) else e.stdout,stderr=e.stderr.decode(errors='replace') if isinstance(e.stderr,bytes) else e.stderr)
 entry['ended_utc']=datetime.datetime.now(datetime.timezone.utc).isoformat();result['commands'].append(entry);return entry
run(['df','-k',str(base)])
run(['df','-h','/'])
roots=[base,pathlib.Path('/Users/alexy/.cargo'),pathlib.Path('/Users/alexy/.cache/uv'),pathlib.Path('/Users/alexy/Library/Caches/Homebrew'),pathlib.Path('/Users/alexy/Library/Caches/pip'),pathlib.Path('/Users/alexy/Library/Caches/colima')]
for p in roots:run(['du','-k','-d','1',str(p)])
selected=['mac-target-d7143e0','mac-target-de8e67098','mac-development','argentea','graph-algorithms','pecan-benchmark','graph-nuts-b87fb27ac','graph-nuts-gate-next','graph-kernels-traversal-1f18','qemu-migration']
for name in selected:run(['du','-k','-d','2',str(base/name)])
paths=[base/'argentea/target-macos-038c9b9597d3/debug',base/'graph-algorithms/target-70b0d1cab2cab945d4dbaf6842ee0e38c8aa1822/debug']
paths += [base/root/component/'debug' for root in ['mac-development','mac-target-d7143e0','mac-target-de8e67098'] for component in ['host','nutmeg','sedona']]
result['intermediate_classes']=[]
for p in paths:
 run(['du','-k','-d','1',str(p)])
 for child in ['deps','incremental']:
  q=p/child
  totals={suffix:{'files':0,'logical_bytes':0,'allocated_bytes':0,'executable_mode_files':0} for suffix in ['.rlib','.rmeta','.o','.d']}
  for directory,folders,files in os.walk(q,followlinks=False):
   folders[:]=[name for name in folders if not pathlib.Path(directory,name).is_symlink()]
   for name in files:
    file=pathlib.Path(directory,name);suffix=file.suffix
    if suffix not in totals:continue
    info=file.lstat()
    if not stat.S_ISREG(info.st_mode):continue
    cell=totals[suffix];cell['files']+=1;cell['logical_bytes']+=info.st_size;cell['allocated_bytes']+=info.st_blocks*512;cell['executable_mode_files']+=int(bool(info.st_mode&0o111))
  result['intermediate_classes'].append({'root':str(q),'suffix_totals':totals,'measurement':'lstat sums of regular files only, no symlink traversal; hard links/APFS shared extents not deduplicated'})
ps=run(['ps','-axo','pid=,ppid=,pgid=,lstart=,comm='])
all_lines=ps.pop('stdout','')
selected=[]
for line in all_lines.splitlines():
 fields=line.strip().split(None,8)
 if len(fields)!=9:continue
 name=pathlib.Path(fields[8]).name.lower()
 if name.startswith(('python','cargo','rustc','rustdoc','clippy','maturin','ninja','cmake','sail')) or name in {'bash','zsh','sh','make','gmake','ld','clang','clang++','gcc','g++','xcrun'}:
  selected.append({'pid':int(fields[0]),'ppid':int(fields[1]),'pgid':int(fields[2]),'lstart':' '.join(fields[3:8]),'comm':fields[8]})
ps['stdout_selected_records']=selected;ps['selection']='process executable names for build/gate candidates only; argv/env not read; unrelated process rows omitted'
result['host_process_check']={'matching_processes':selected,'limits':'Generic Python/shell names alone cannot establish absence of a gate; cwd capture below is additional context. No process is signalled.'}
if selected:
 run(['/usr/sbin/lsof','-a','-p',','.join(str(x['pid']) for x in selected),'-d','cwd','-Fn'],20)
result['ended_utc']=datetime.datetime.now(datetime.timezone.utc).isoformat()
print(json.dumps(result))
